const fs = require('fs');
const MOD = 1000000007;
let count = 0, sum = 0n, max = 0;

const stream = fs.createReadStream('data.txt', { encoding: 'utf8', highWaterMark: 1 << 20 });
let tail = '';

stream.on('data', (chunk) => {
  const buf = tail + chunk;
  let start = 0, idx;
  while ((idx = buf.indexOf('\n', start)) !== -1) {
    const line = buf.slice(start, idx).trim();
    if (line.length) {
      const n = Number(line);
      count++;
      if (n > max) max = n;
      sum += BigInt(n);
      if (sum > 1000000000000000n) sum %= BigInt(MOD);
    }
    start = idx + 1;
  }
  tail = buf.slice(start);
});

stream.on('end', () => {
  const line = tail.trim();
  if (line.length) {
    const n = Number(line);
    count++;
    if (n > max) max = n;
    sum += BigInt(n);
  }
  console.log(JSON.stringify({ count, sum: Number(sum % BigInt(MOD)), max }));
});

stream.on('error', (e) => { console.error(e.message); process.exit(1); });

const fs = require('fs');
const { spawnSync } = require('child_process');

const src = [
  "const fs = require('fs');",
  "const MOD = 1000000007;",
  "let count = 0, sum = 0, max = 0;",
  "function add(t) {",
  "  const v = Number(t);",
  "  count++;",
  "  sum = (sum + v) % MOD;",
  "  if (v > max) max = v;",
  "}",
  "const stream = fs.createReadStream('data.txt', { encoding: 'utf8', highWaterMark: 65536 });",
  "let carry = '';",
  "stream.on('data', (d) => {",
  "  const s = carry + d;",
  "  let start = 0, idx;",
  "  while ((idx = s.indexOf('\\n', start)) !== -1) {",
  "    const t = s.slice(start, idx);",
  "    if (t.length) add(t);",
  "    start = idx + 1;",
  "  }",
  "  carry = s.slice(start);",
  "});",
  "stream.on('end', () => {",
  "  if (carry.length) add(carry);",
  "  process.stdout.write(JSON.stringify({ count: count, sum: sum, max: max }) + '\\n');",
  "});",
  ""
].join('\n');

fs.writeFileSync('sum.js', src);

// --- self test on a tiny file ---
fs.writeFileSync('test.txt', '1\n2\n3\n1000000007\n999999999\n');
fs.writeFileSync('sumtest.js', src.replace("'data.txt'", "'test.txt'"));
const t = spawnSync(process.execPath, ['--max-old-space-size=128', 'sumtest.js'], { encoding: 'utf8' });
const tOut = (t.stdout || '').trim();
const expectCount = 5n;
const nums = [1n, 2n, 3n, 1000000007n, 999999999n];
const expectSum = nums.reduce((a, b) => (a + b) % 1000000007n, 0n);
const expectMax = nums.reduce((a, b) => (b > a ? b : a), 0n);
let testOk = false;
try {
  const j = JSON.parse(tOut);
  testOk = BigInt(j.count) === expectCount && BigInt(j.sum) === expectSum && BigInt(j.max) === expectMax;
} catch (e) { testOk = false; }
console.log('selftest', t.status, tOut, 'ok=' + testOk);

// --- count lines of data.txt independently ---
let lines = 0, lastByte = 10;
const fd = fs.openSync('data.txt', 'r');
const buf = Buffer.alloc(1 << 16);
while (true) {
  const n = fs.readSync(fd, buf, 0, buf.length, null);
  if (n <= 0) break;
  for (let i = 0; i < n; i++) if (buf[i] === 10) lines++;
  lastByte = buf[n - 1];
}
fs.closeSync(fd);
if (lastByte !== 10) lines++;
console.log('file lines =', lines);

// --- real run under memory cap ---
const r = spawnSync(process.execPath, ['--max-old-space-size=128', 'sum.js'], { encoding: 'utf8', maxBuffer: 1 << 24 });
console.log('exit=' + r.status);
console.log('stdout=' + (r.stdout || '').trim());
if (r.stderr) console.log('stderr=' + r.stderr.slice(0, 500));

let realOk = false, j = null;
try { j = JSON.parse((r.stdout || '').trim()); } catch (e) {}
if (r.status === 0 && j && j.count === lines && j.max >= 0) realOk = true;

if (testOk && realOk) {
  console.log('DONE: ' + (r.stdout || '').trim());
} else {
  console.log('NOT DONE');
}
